<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between"><span>商家等级</span><el-button type="primary" size="small" @click="showDialog=true">新增等级</el-button></div></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="name" label="等级名称"/><el-table-column prop="description" label="描述" show-overflow-tooltip/><el-table-column prop="commission_rate" label="佣金比例(%)" width="120"/><el-table-column prop="sort" label="排序" width="80"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'" size="small">{{row.status===1?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="showDialog" :title="form.id?'编辑等级':'新增等级'" width="500px"><el-form :model="form" label-width="100px"><el-form-item label="等级名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item><el-form-item label="佣金比例"><el-input-number v-model="form.commission_rate" :min="0" :max="100" :precision="2"/>%</el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template><script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const showDialog=ref(false);const form=reactive({id:null,name:'',description:'',commission_rate:0,sort:0,status:1});const loadList=async()=>{const res=await request({url:'/admin/merchant-levels'});list.value=res.data||[]};const edit=(row)=>{Object.assign(form,row);showDialog.value=true};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/admin/merchant-levels/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};const submit=async()=>{if(form.id)await request({url:`/admin/merchant-levels/${form.id}`,method:'put',data:form});else await request({url:'/admin/merchant-levels',method:'post',data:form});ElMessage.success('保存成功');showDialog.value=false;loadList()};onMounted(()=>loadList())</script>
